#include <Wire.h>
#include <LiquidCrystal_I2C.h>

// Инициализация дисплея: адрес 0x27, 16 символов, 2 строки
// Если экран пустой и не реагирует, попробуйте заменить 0x27 на 0x3F
LiquidCrystal_I2C lcd(0x27, 16, 2);

const int BTN_PIN = 2;    // Кнопка
const int LED_PIN = 8;    // Светодиод
const int BUZ_PIN = 9;    // Зуммер

bool alarmActive = false;
bool lastButtonState = HIGH;
unsigned long lastDebounceTime = 0;
const unsigned long debounceDelay = 50;

void setup() {
  pinMode(BTN_PIN, INPUT_PULLUP);
  pinMode(LED_PIN, OUTPUT);
  pinMode(BUZ_PIN, OUTPUT);

  digitalWrite(LED_PIN, LOW);
  digitalWrite(BUZ_PIN, LOW);

  // Запуск дисплея
  lcd.init();
  lcd.backlight(); // Включить подсветку

  // Начальный экран
  lcd.setCursor(0, 0);
  lcd.print("System Ready");
}

void loop() {
  bool reading = digitalRead(BTN_PIN);

  if (reading != lastButtonState) {
    lastDebounceTime = millis();
  }

  if ((millis() - lastDebounceTime) > debounceDelay) {
    if (reading == LOW) {
      alarmActive = !alarmActive; // Переключаем состояние

      if (alarmActive) {
        // Включилась тревога
        lcd.clear();
        lcd.setCursor(0, 0);
        lcd.print("ALARM TRIGGERED!");
        lcd.setCursor(0, 1);
        lcd.print("Button pressed");

        digitalWrite(LED_PIN, HIGH);
        tone(BUZ_PIN, 1000); // Звук 1000 Гц (если пассивный зуммер)
      } else {
        // Тревога выключена
        lcd.clear();
        lcd.setCursor(0, 0);
        lcd.print("System Ready");

        digitalWrite(LED_PIN, LOW);
        noTone(BUZ_PIN); // Выключаем звук
      }

      // Защита от двойного нажатия
      while(digitalRead(BTN_PIN) == LOW) { delay(10); }
    }
  }
  lastButtonState = reading;
}
